// src/utils/animations/particles/star-particle.ts
import { ParticleBase } from '../core/particle-base';
import { ParticleOptions, Vector2D } from '../core/types';

export class StarParticle extends ParticleBase {
  private twinkleSpeed: number;
  private twinkleDirection: number;
  private maxOpacity: number;
  private minOpacity: number;
  private baseSize: number;
  private sizeVariation: number;

  constructor(
    containerWidth: number,
    containerHeight: number,
    options: ParticleOptions
  ) {
    super(containerWidth, containerHeight, options);
    
    // Star-specific properties
    this.twinkleSpeed = 0.01 + Math.random() * 0.03;
    this.twinkleDirection = Math.random() > 0.5 ? 1 : -1;
    
    // Get opacity range from options
    this.maxOpacity = options.opacity?.max || 1.0;
    this.minOpacity = options.opacity?.min || 0.3;
    
    // Store original size for variation
    const state = this.getState();
    this.baseSize = state.size;
    this.sizeVariation = this.baseSize * 0.2;
    
    // Initialize position randomly across the screen
    // Use the state object or modify properties directly based on what ParticleBase allows
    const position: Vector2D = {
      x: Math.random() * containerWidth,
      y: Math.random() * containerHeight
    };
    
    // Using property setter method with direct property access
    this.position = { ...position };
    
    // Stars don't move
    this.velocity = { x: 0, y: 0 };
    
    // Set initial opacity randomly
    this.opacity = this.minOpacity + Math.random() * (this.maxOpacity - this.minOpacity);
    
    // Set color - stars can be white, yellow, or light blue
    const colors = options.colors || ['#FFFFFF', '#FFFFD9', '#E8F1FF'];
    this.color = colors[Math.floor(Math.random() * colors.length)];
  }

  update(deltaTime: number): boolean {
    // Update twinkling effect
    this.twinkle(deltaTime);
    
    // Call parent update to handle standard behavior
    return super.update(deltaTime);
  }

  private twinkle(deltaTime: number): void {
    // Update opacity for twinkle effect
    this.opacity += this.twinkleSpeed * this.twinkleDirection * deltaTime;
    
    // Reverse direction at opacity limits
    if (this.opacity >= this.maxOpacity) {
      this.opacity = this.maxOpacity;
      this.twinkleDirection = -1;
    } else if (this.opacity <= this.minOpacity) {
      this.opacity = this.minOpacity;
      this.twinkleDirection = 1;
    }
    
    // Slight size variation based on opacity
    const sizeVariation = (this.opacity - this.minOpacity) / (this.maxOpacity - this.minOpacity);
    this.size = this.baseSize + this.sizeVariation * sizeVariation;
  }

  // Factory method for creating star particles
  static create(
    containerWidth: number,
    containerHeight: number,
    options: ParticleOptions
  ): ParticleBase {
    return new StarParticle(containerWidth, containerHeight, options);
  }
}
